// Compares every endpoint path used in the plan against the real,
// documented endpoint paths. Pure string comparison - no AI involved.
const doc = $('API Documentation (JSON)').first().json;
const validPaths = doc.endpoints.map(e => e.path);

const plan = $json.output;
const usedPaths = (plan.endpoint_details || []).map(e => e.path);
const invented = usedPaths.filter(p => !validPaths.includes(p));

return [{
  json: {
    ...$json,
    deterministic_check_passed: invented.length === 0,
    invented_endpoints: invented,
    valid_endpoint_paths_reference: validPaths
  }
}];
